      "content": "import { assert } from 'node:assert/strict';
class LeaseManager {
  constructor(maxConcurrent = 2) {
    this.maxConcurrent = maxConcurrent;
    this.leases = new Map(); // subjectKey => expiry timestamp (ms)
  }

  _validateSubjectKey(key) {
    if (typeof key !== 'string' || key.trim() === '') {
      throw new Error('Invalid subject key');
    }
  }

  _validateTTL(ttlMs) {
    if (typeof ttlMs !== 'number' || ttlMs <= 0) {
      throw new Error('TTL must be a positive number');
    }
  }

  grant(subjectKey, ttlMs) {
    this._validateSubjectKey(subjectKey);
    this._validateTTL(ttlMs);

    const now = Date.now();
    const existingExpiry = this.leases.get(subjectKey);
    if (existingExpiry && existingExpiry > now) {
      // Already has an active lease
      return false;
    }

    const currentActiveCount = [...this.leases.values()].filter(exp => exp > now).length;
    if (currentActiveCount >= this.maxConcurrent) {
      return false; // capacity reached
    }

    const expiry = now + ttlMs;
    this.leases.set(subjectKey, expiry);
    return true;
  }

  deny(subjectKey) {
    this._validateSubjectKey(subjectKey);
    const now = Date.now();
    const expiry = this.leases.get(subjectKey);
    if (!expiry || expiry <= now) {
      // No active lease to deny
      return false;
    }
    this.leases.delete(subjectKey);
    return true;
  }

  isGranted(subjectKey) {
    this._validateSubjectKey(subjectKey);
    const expiry = this.leases.get(subjectKey);
    if (!expiry) return false;
    const now = Date.now();
    return expiry > now;
  }
}
export { LeaseManager };",
