      "content": "import test from 'node:test';
import assert from 'node:assert/strict';
import { LeaseManager } from './leaseManager.js';

test('LeaseManager grants a lease for a valid subject key', () => {
  const manager = new LeaseManager();
  const result = manager.grant('alpha', 1000);
  assert.strictEqual(result, true);
  assert.strictEqual(manager.isGranted('alpha'), true);
});

test('LeaseManager denies an existing lease', () => {
  const manager = new LeaseManager();
  manager.grant('beta', 1000);
  const denied = manager.deny('beta');
  assert.strictEqual(denied, true);
  assert.strictEqual(manager.isGranted('beta'), false);
});

test('LeaseManager rejects grant when capacity is exceeded', () => {
  const manager = new LeaseManager(2);
  // Fill capacity
  manager.grant('first', 1000);
  manager.grant('second', 1000);
  const thirdGrant = manager.grant('third', 1000);
  assert.strictEqual(thirdGrant, false);
});

test('LeaseManager rejects invalid subject key', () => {
  const manager = new LeaseManager();
  assert.throws(() => manager.grant('', 1000), /Invalid subject key/);
  assert.throws(() => manager.grant(null, 1000), /Invalid subject key/);
  assert.throws(() => manager.grant(123, 1000), /Invalid subject key/);
});

test('LeaseManager rejects grant with invalid TTL', () => {
  const manager = new LeaseManager();
  assert.throws(() => manager.grant('key', 0), /TTL must be a positive number/);
  assert.throws(() => manager.grant('key', -100), /TTL must be a positive number/);
  assert.throws(() => manager.grant('key', 'invalid'), /TTL must be a positive number/);
});

test('LeaseManager does not grant duplicate active lease', () => {
  const manager = new LeaseManager();
  manager.grant('dup', 500);
  const secondGrant = manager.grant('dup', 500);
  assert.strictEqual(secondGrant, false);
});

test('LeaseManager reflects lease expiry after TTL', async () => {
  const manager = new LeaseManager();
  manager.grant('expiring', 10);
  assert.strictEqual(manager.isGranted('expiring'), true);
  await new Promise(resolve => setTimeout(resolve, 15));
  assert.strictEqual(manager.isGranted('expiring'), false);
});
